$ErrorActionPreference = 'Stop'
$projectRoot = Split-Path -Parent $PSScriptRoot
$pagePath = Join-Path $projectRoot 'admin-panel\app\sahaba\page.tsx'
$source = [IO.File]::ReadAllText($pagePath)

$source = $source.Replace('[working,setWorking]=useState("");', '[working,setWorking]=useState(""),[languageOpen,setLanguageOpen]=useState(false),[languageSearch,setLanguageSearch]=useState("");')

$oldPicker = '<label>Language <small>195 available</small><select value={form.languageCode} onChange={e=>{const selected=languages.find(item=>item.code===e.target.value);setForm({...form,languageCode:e.target.value,language:selected?.label||e.target.value.toUpperCase()})}}>{languages.map(item=><option key={item.code} value={item.code}>{item.label} ({item.code.toUpperCase()})</option>)}</select></label>'
$newPicker = '<label>Language <small>195 available</small><button type="button" className="languagePicker" onClick={()=>setLanguageOpen(true)}><i>{form.languageCode.toUpperCase()}</i><span><b>{languages.find(item=>item.code===form.languageCode)?.label||form.language}</b><small>Select content language</small></span><strong>›</strong></button></label>'
$source = $source.Replace($oldPicker, $newPicker)

$marker = '</section></section><style jsx>{`'
$modal = '</section></section>{languageOpen&&<div className="languageModal" role="dialog" aria-modal="true" aria-label="Select Sahaba content language"><section><div className="languageModalHead"><div><small>SAHABA CONTENT</small><h2>Select Language</h2><p>{new Set(items.map(item=>item.languageCode||"en")).size} languages uploaded · 195 available</p></div><button type="button" onClick={()=>{setLanguageOpen(false);setLanguageSearch("")}}>×</button></div><label className="languageSearch"><span>⌕</span><input autoFocus value={languageSearch} onChange={e=>setLanguageSearch(e.target.value)} placeholder="Search language or code..."/></label><div className="languageList">{languages.filter(item=>!languageSearch.trim()||`${item.label} ${item.code}`.toLowerCase().includes(languageSearch.trim().toLowerCase())).map(item=>{const count=items.filter(book=>(book.languageCode||"en")===item.code).length,selected=form.languageCode===item.code;return <button type="button" key={item.code} className={selected?"languageRow selected":"languageRow"} onClick={()=>{setForm({...form,languageCode:item.code,language:item.label});setLanguageOpen(false);setLanguageSearch("")}}><i>{item.code.slice(0,3).toUpperCase()}</i><span><b>{item.label}{item.code==="en"?" (Base)":""}</b><small>{count?`${count} ${count===1?"biography":"biographies"} uploaded`:"Not uploaded yet"}</small></span>{count>0?<em>✓</em>:<em className="emptyMark"/>}<strong>›</strong></button>})}</div></section></div>}<style jsx>{`'
$source = $source.Replace($marker, $modal)

$cssMarker = '@media(max-width:1000px)'
$css = '.languagePicker{width:100%;min-height:54px;margin-top:6px;padding:8px 12px;display:flex;align-items:center;gap:10px;border:1px solid #cbded1;border-radius:10px;background:#fff;color:#173d2e;text-align:left}.languagePicker>i{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#eaf4ed;color:#087a4d;font-size:10px;font-style:normal;font-weight:900}.languagePicker>span{display:block;flex:1}.languagePicker>span b,.languagePicker>span small{display:block}.languagePicker>span small{margin-top:3px;color:#7b8981;font-weight:500}.languagePicker>strong{color:#087a4d;font-size:24px}.languageModal{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:20px;background:#123c2fb3;backdrop-filter:blur(5px)}.languageModal>section{width:min(560px,100%);max-height:88vh;display:flex;flex-direction:column;padding:22px;border-radius:24px;background:#f9fcfa;box-shadow:0 24px 70px #102d2340}.languageModalHead{display:flex;align-items:flex-start;justify-content:space-between}.languageModalHead small{color:#a27f24;font-size:10px;font-weight:900;letter-spacing:1.2px}.languageModalHead h2{margin:5px 0 2px;font-family:Georgia,serif;font-size:29px}.languageModalHead p{margin:0;color:#718078;font-size:12px}.languageModalHead>button{width:40px;height:40px;padding:0;border:0;border-radius:50%;background:#e8f4eb;color:#087a4d;font-size:18px;font-weight:900}.languageSearch{position:relative;margin-top:16px}.languageSearch span{position:absolute;left:16px;top:19px;color:#087a4d;font-size:21px}.languageSearch input{height:50px;margin:0;padding-left:44px;font-size:13px;font-weight:700}.languageList{display:grid;gap:8px;margin-top:14px;padding-right:4px;overflow:auto}.languageRow{width:100%;display:flex;align-items:center;gap:12px;padding:11px 13px;border:1px solid #d6e5da;border-radius:15px;background:#fff;color:#173d2e;text-align:left}.languageRow.selected{border-color:#61ad7d;background:#f0faf3}.languageRow>i{width:40px;height:40px;display:grid;place-items:center;flex:none;border-radius:50%;background:#edf3ef;color:#65776e;font-size:9px;font-style:normal;font-weight:900}.languageRow>span{min-width:0;flex:1}.languageRow>span b,.languageRow>span small{display:block}.languageRow>span b{font-size:14px}.languageRow>span small{margin-top:4px;color:#7d8b84;font-size:10px}.languageRow>em{width:20px;height:20px;display:grid;place-items:center;border-radius:50%;background:#0a955b;color:#fff;font-style:normal;font-weight:900}.languageRow>em.emptyMark{background:#e7f0ea}.languageRow>strong{color:#079052;font-size:22px}' + $cssMarker
$source = $source.Replace($cssMarker, $css)

[IO.File]::WriteAllText($pagePath, $source, [Text.UTF8Encoding]::new($false))
